package org.medsupply;
import java.nio.file.Files;import java.nio.file.Path;
public final class EventStoreTest {public static void main(String[] args)throws Exception{Path shared=Files.createTempDirectory("medsupply-shared");EventStore a=new EventStore(shared,Files.createTempDirectory("medsupply-localA"));a.append(event("STOCK_RECEIVED","2026-08-03T10:00:00Z","5"));a.append(event("STOCK_PICKED","2026-08-03T11:00:00Z","-2"));EventStore.LoadResult loaded=new EventStore(shared,Files.createTempDirectory("medsupply-localB")).loadAll();check(loaded.errors.isEmpty(),"errors "+loaded.errors);check(loaded.events.size()==2,"count");check("STOCK_RECEIVED".equals(loaded.events.get(0).eventType),"sort");check(a.pendingCount()==0,"pending");System.out.println("EventStoreTest: PASS");}private static SupplyEvent event(String type,String occurred,String delta){SupplyEvent e=new SupplyEvent();e.eventType=type;e.deviceId="WS-A";e.occurredUtc=occurred;e.recordedUtc=occurred;e.payload.put("quantityDelta",delta);return e;}private static void check(boolean c,String s){if(!c)throw new AssertionError("Failed: "+s);}}
